-- pintopets_diet_items: tenant-scoped rows behind /diet-items (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_diet_items (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            created_by_user_uuid UUID NOT NULL,
            kind VARCHAR(255) NOT NULL,
            brand VARCHAR(255),
            product VARCHAR(255) NOT NULL,
            amount VARCHAR(255),
            frequency VARCHAR(255),
            started_on DATE,
            ended_on DATE,
            notes TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT pintopets_diet_items_kind_check CHECK (kind IN ('food', 'treat', 'supplement'))
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_diet_items_namespace ON pintopets_diet_items (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_diet_items_pet ON pintopets_diet_items (namespace_id, pet_uuid)")
end
